import { useEffect, useMemo, useState } from 'react'
import {
  Activity, Bell, BriefcaseBusiness, CalendarDays, Check, ChevronDown, ChevronLeft,
  ChevronRight, CircleDollarSign, Clock3, CreditCard, Ellipsis, FileCheck2, Grid2X2,
  HeartPulse, LayoutDashboard, ListChecks, Menu, MoreHorizontal, Plus, Search, Settings,
  Sparkles, Target, UserRound, UsersRound, WalletCards, X, Zap,
} from 'lucide-react'
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { agenda, Vertical, verticalLabels } from './data'
import { useDemoStore } from './store'

type Page = 'dashboard' | 'accounts' | 'account' | 'opportunities' | 'opportunity' | 'agenda' | 'work' | 'engagement' | 'prestations' | 'activities' | 'payments' | 'services' | 'settings'
type Navigate = (page: Page, query?: Record<string, string | number>) => void
type Labels = typeof verticalLabels[Vertical]
const newAccountLabel = (labels: Labels) => `${labels.account === 'Marca' ? 'Nueva' : 'Nuevo'} ${labels.account.toLowerCase()}`
const newPrestationLabel = (labels: Labels) => `${labels.prestation === 'Atención' ? 'Nueva' : 'Nuevo'} ${labels.prestation.toLowerCase()}`

const money = (value: string) => value
const trend = [
  { month: 'Mar', income: 2140, pending: 410 }, { month: 'Abr', income: 2680, pending: 520 },
  { month: 'May', income: 2520, pending: 360 }, { month: 'Jun', income: 3040, pending: 610 },
  { month: 'Jul', income: 2890, pending: 490 }, { month: 'Ago', income: 3420, pending: 420 },
]

const cls = (...parts: Array<string | false | undefined>) => parts.filter(Boolean).join(' ')

const pagePaths: Record<Page, string> = {
  dashboard: '/', accounts: '/cuentas', account: '/cuentas/detalle', opportunities: '/oportunidades',
  opportunity: '/oportunidades/detalle', agenda: '/agenda', work: '/trabajo', engagement: '/trabajo/detalle',
  prestations: '/prestaciones', activities: '/actividades', payments: '/pagos', services: '/servicios', settings: '/configuracion',
}

function pageFromLocation(): Page {
  const entry = Object.entries(pagePaths).find(([, path]) => path === window.location.pathname)
  return (entry?.[0] as Page | undefined) || 'dashboard'
}

function useAppRoute() {
  const [page, setPage] = useState<Page>(pageFromLocation)
  useEffect(() => {
    const onPopState = () => setPage(pageFromLocation())
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])
  const go = (next: Page, query?: Record<string, string | number>) => {
    const search = query ? `?${new URLSearchParams(Object.entries(query).map(([key, value]) => [key, String(value)])).toString()}` : ''
    window.history.pushState({}, '', `${pagePaths[next]}${search}`)
    setPage(next)
    window.scrollTo(0, 0)
  }
  return { page, go }
}

function StatusBadge({ children, tone }: { children: React.ReactNode; tone?: string }) {
  const t = tone || String(children).toLowerCase()
  return <span className={cls('badge', `badge-${t.replaceAll(' ', '-')}`)}>{children}</span>
}

function PageHeader({ eyebrow, title, description, action, onAction }: { eyebrow?: string; title: string; description?: string; action?: string; onAction?: () => void }) {
  return <div className="page-header">
    <div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description && <p>{description}</p>}</div>
    {action && <button className="primary-btn" onClick={onAction}><Plus size={17} />{action}</button>}
  </div>
}

function MetricCard({ label, value, meta, icon: Icon, tone = 'violet' }: { label: string; value: string; meta: string; icon: React.ElementType; tone?: string }) {
  return <article className="metric-card card">
    <div className={cls('metric-icon', tone)}><Icon size={19} /></div>
    <div className="metric-label">{label}</div>
    <div className="metric-value">{value}</div>
    <div className="metric-meta">{meta}</div>
  </article>
}

function EmptyState({ title, body, action, onAction }: { title: string; body: string; action: string; onAction: () => void }) {
  return <div className="empty-state"><div className="empty-icon"><Sparkles size={22} /></div><h3>{title}</h3><p>{body}</p><button className="secondary-btn" onClick={onAction}><Plus size={16} />{action}</button></div>
}

function Modal({ title, subtitle, onClose, children, wide }: { title: string; subtitle?: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) {
  return <div className="modal-backdrop" onMouseDown={onClose}><section className={cls('modal', wide && 'modal-wide')} role="dialog" aria-modal="true" aria-label={title} onMouseDown={e => e.stopPropagation()}>
    <header><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-btn" aria-label="Cerrar" onClick={onClose}><X size={19} /></button></header>{children}
  </section></div>
}

function CreateForm({ type, labels, onDone }: { type: string; labels: typeof verticalLabels[Vertical]; onDone: () => void }) {
  const store = useDemoStore()
  const lower = type.toLowerCase()
  const mode = lower.includes('pago') ? 'payment' : lower.includes('oportunidad') ? 'opportunity' : lower.includes(labels.account.toLowerCase()) ? 'account' : lower.includes(labels.engagement.toLowerCase()) ? 'engagement' : lower.includes(labels.prestation.toLowerCase()) ? 'prestation' : lower.includes('actividad') ? 'activity' : 'service'
  const [accountName, setAccountName] = useState(store.accounts[0]?.name || '')
  const [serviceId, setServiceId] = useState(store.services[0]?.id || 0)
  const [allocated, setAllocated] = useState<number[]>([])
  const selectedService = store.services.find(service => service.id === serviceId)
  const pending = store.prestations.filter(prestation => prestation.account === accountName && prestation.payment !== 'Pagado')

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const values = Object.fromEntries(new FormData(event.currentTarget).entries())
    const name = String(values.name || '').trim()
    if (mode === 'account') {
      store.addAccount({ name, type: String(values.accountType || 'Persona'), status: 'Prospecto', last: 'Ahora', next: '—', income: '$0', pending: '$0', email: String(values.email || ''), phone: String(values.phone || ''), rut: String(values.rut || '') })
    } else if (mode === 'opportunity') {
      store.addOpportunity({ account: accountName, title: name, amount: String(values.amount || '$0'), close: '30 Ago', contact: accountName, last: 'Ahora', stage: 'Nuevo' })
    } else if (mode === 'engagement') {
      store.addEngagement({ name, account: accountName, type: labels.engagement, progress: 0, detail: `0 ${labels.prestations.toLowerCase()}`, amount: String(values.amount || '$0'), status: 'Activo' })
    } else if (mode === 'prestation') {
      store.addPrestation({ date: `${String(values.date || '17 Ago')} · ${String(values.time || '09:00')}`, account: accountName, name: selectedService?.name || name, origin: String(values.origin || 'Directa'), status: 'Programada', amount: selectedService?.price || String(values.amount || '$0'), payment: 'Pendiente' })
    } else if (mode === 'activity') {
      store.addActivity({ title: name, relation: `${accountName} · ${String(values.activityType || 'Tarea')}`, date: 'Hoy', type: String(values.activityType || 'Tarea'), status: 'Pendiente' })
    } else if (mode === 'payment') {
      store.addPayment({ date: 'Hoy', account: accountName, amount: String(values.amount || '$0'), method: String(values.method || 'Transferencia'), status: 'Pagado', allocations: allocated.length ? `${allocated.length} ${labels.prestations.toLowerCase()}` : 'Sin asignar' }, allocated)
    } else {
      store.addService({ name, description: String(values.description || ''), duration: `${String(values.duration || '60')} min`, price: String(values.amount || '$0'), active: true })
    }
    onDone()
  }

  return <form onSubmit={submit}>
    <div className="form-grid">
      {mode !== 'account' && mode !== 'service' && <label><span>{labels.account} *</span><select required value={accountName} onChange={event => setAccountName(event.target.value)}>{store.accounts.map(account => <option key={account.id}>{account.name}</option>)}</select></label>}
      {mode === 'account' && <><label><span>Nombre *</span><input name="name" required autoFocus placeholder={`Nombre del ${labels.account.toLowerCase()}`} /></label><label><span>Tipo</span><select name="accountType"><option>Persona</option><option>Empresa</option><option>Marca</option></select></label><label><span>Email</span><input name="email" type="email" /></label><label><span>Teléfono</span><input name="phone" /></label><label><span>RUT</span><input name="rut" /></label></>}
      {mode === 'opportunity' && <><label><span>Oportunidad *</span><input name="name" required autoFocus placeholder="Ej. Plan de 8 sesiones" /></label><label><span>Monto estimado</span><input name="amount" placeholder="$0" /></label><label><span>Cierre estimado</span><input name="date" type="date" defaultValue="2026-08-30" /></label><label><span>Etapa</span><select name="stage"><option>Nuevo</option><option>Contactado</option><option>Propuesta</option><option>Negociación</option></select></label></>}
      {mode === 'engagement' && <><label><span>Nombre *</span><input name="name" required autoFocus placeholder={`Nombre del ${labels.engagement.toLowerCase()}`} /></label><label><span>Monto acordado</span><input name="amount" placeholder="$0" /></label><label><span>Modalidad</span><select name="billing"><option>Puntual</option><option>Recurrente</option></select></label><label><span>Inicio</span><input name="date" type="date" defaultValue="2026-08-17" /></label></>}
      {mode === 'prestation' && <><label><span>{labels.service}</span><select value={serviceId} onChange={event => setServiceId(Number(event.target.value))}>{store.services.filter(service => service.active).map(service => <option value={service.id} key={service.id}>{service.name}</option>)}</select></label><label><span>Fecha</span><input name="date" type="date" defaultValue="2026-08-17" /></label><label><span>Hora</span><input name="time" type="time" defaultValue="09:00" /></label><label><span>Duración sugerida</span><input disabled value={selectedService?.duration || '—'} /></label><label><span>Precio sugerido</span><input disabled value={selectedService?.price || '$0'} /></label><label><span>Origen</span><select name="origin"><option>Directa</option><option>{labels.engagement}</option></select></label></>}
      {mode === 'activity' && <><label><span>Título *</span><input name="name" required autoFocus placeholder="Qué necesitas hacer" /></label><label><span>Tipo</span><select name="activityType">{['Tarea','Llamada','Reunión','Email','WhatsApp','Nota','Hito'].map(item => <option key={item}>{item}</option>)}</select></label><label><span>Fecha</span><input name="date" type="date" defaultValue="2026-08-17" /></label><label><span>Hora</span><input name="time" type="time" defaultValue="09:00" /></label></>}
      {mode === 'payment' && <><label><span>Monto *</span><input name="amount" placeholder="$0" required autoFocus /></label><label><span>Fecha</span><input name="date" type="date" defaultValue="2026-08-17" /></label><label><span>Método</span><select name="method"><option>Transferencia</option><option>Efectivo</option><option>Tarjeta</option></select></label><label><span>Estado</span><select name="status"><option>Pagado</option><option>Pendiente</option></select></label></>}
      {mode === 'service' && <><label><span>Nombre *</span><input name="name" required autoFocus placeholder={labels.service} /></label><label><span>Precio sugerido</span><input name="amount" required placeholder="$0" /></label><label><span>Duración (min)</span><input name="duration" type="number" defaultValue="60" /></label><label><span>Descripción</span><input name="description" /></label></>}
    </div>
    {mode === 'payment' && <div className="allocation-box"><div><strong>Asignar a {labels.prestations.toLowerCase()} pendientes</strong><p>El saldo de pago se calcula desde estas asignaciones; no se duplica en la prestación.</p></div>{pending.length ? pending.map(prestation => <label className="allocation" key={prestation.id}><input type="checkbox" checked={allocated.includes(prestation.id)} onChange={() => setAllocated(current => current.includes(prestation.id) ? current.filter(id => id !== prestation.id) : [...current, prestation.id])} /><span>{prestation.date}<b>{prestation.name}</b></span><strong>{prestation.amount}</strong></label>) : <p className="form-empty">Esta cuenta no tiene prestaciones pendientes.</p>}</div>}
    <footer className="modal-actions"><button type="button" className="ghost-btn" onClick={onDone}>Cancelar</button><button className="primary-btn">Guardar</button></footer>
  </form>
}

